import test from 'node:test';import assert from 'node:assert/strict';import {flow,earnOpening} from './opening-flow.mjs';import {installFieldFeedback,inspectionChanges,isFieldInspection} from '../field-feedback.js';
function setup(){const h=earnOpening(),events=[];installFieldFeedback(h.w,e=>events.push(e));return{...h,events};}
function locate(w,predicate){const scene=w.data.scenes.find(s=>!s.originId&&s.objects.some(predicate));w.state.scene=scene.location;w.state.mode='field';w.state.story.parcel=true;const o=scene.objects.find(predicate);w.state.x=o.xy[0]+.5;w.state.y=o.xy[1]+.5;return o;}
test('furnishings inspect and shared remedies collect in field, once across save restoration',()=>{const {w,events}=setup();const o=locate(w,o=>o.type==='furnishing'&&o.supply);const before=w.state.items[o.supply]||0;w.interact(o);assert.equal(w.state.mode,'field');assert.equal(events.length,1);assert.equal(events[0].actions.length,0);assert.equal(w.state.items[o.supply],before+1);assert.ok(events[0].effects.some(e=>e.text.includes('Moss wrap')));assert.ok(w.state.household.openFurniture.includes(o.householdId));w.restore(w.save());w.interact(w.scene.objects.find(v=>v.householdId===o.householdId));assert.equal(w.state.items[o.supply],before+1);assert.equal(events.at(-1).effects.length,0);});
test('cupboard inspection changes visible open state without dialogue or moving possessions',()=>{const{w,events}=setup();const o=locate(w,o=>o.type==='furnishing'&&[1,2,7,10,12,19,20].includes(o.furniture)&&!o.supply),items=JSON.stringify(w.state.items);w.interact(o);assert.ok(w.state.household.openFurniture.includes(o.householdId));assert.equal(w.state.mode,'field');w.interact(o);assert.ok(!w.state.household.openFurniture.includes(o.householdId));assert.equal(JSON.stringify(w.state.items),items);assert.equal(events.length,2);});
test('warming at a hearth applies the existing strain relief and reports its actual effect',()=>{const{w,events}=setup();const o=locate(w,o=>o.type==='furnishing'&&[3,4].includes(o.furniture));for(const h of w.activeHeroes)h.strain=15;w.interact(o);assert.equal(w.state.mode,'field');assert.ok(w.activeHeroes.every(h=>h.strain===7));assert.ok(events.at(-1).effects.some(e=>e.kind==='restore'));});
test('a hidden cache pays normally, retains every note, and never blocks walking',()=>{const{w,events}=setup();const o=locate(w,o=>o.type==='secret'&&!o.lock);w.interact(o);assert.equal(w.state.mode,'field');assert.ok(w.state.exploration.found.includes(o.exploreId));assert.ok(events.at(-1).effects.length);assert.ok(events.at(-1).pages.length>1);assert.equal(w.state.fieldNotes.at(-1).label,events.at(-1).label);const before=w.state.gold;w.interact(o);assert.equal(w.state.gold,before);});
test('real environmental choices use field actions and reject actions after walking away or entering battle',()=>{const{w,events}=setup();const o=locate(w,o=>o.type==='riddle');w.interact(o);assert.equal(w.state.mode,'field');assert.equal(events.at(-1).actions.length,o.options.length);const choice=events.at(-1).actions[o.answer];w.state.x=o.xy[0]+10;assert.equal(choice.action(),false);assert.ok(!w.state.exploration.solved.includes(o.exploreId));w.state.x=o.xy[0]+.5;w.state.mode='battle';assert.equal(choice.action(),false);w.state.mode='field';assert.equal(choice.action(),true);assert.ok(w.state.exploration.solved.includes(o.exploreId));assert.equal(w.state.mode,'field');});
test('ordinary story dialogue and meaningful plot choices retain the original callback lifecycle',()=>{const h=flow();let count=0;installFieldFeedback(h.w,()=>count++);h.use(h.w.objects().find(o=>o.type==='npc'));assert.equal(count,0);assert.equal(h.w.state.story.parcel,true);assert.equal(isFieldInspection({type:'npc',storyEvent:'iona'}),false);assert.equal(isFieldInspection({type:'puzzle',originId:'sable-reed'}),false);assert.equal(isFieldInspection({type:'npc',life:true,lifeKind:'resident'}),false);});
test('field receipts describe actual item, currency and Mako changes rather than repeating arbitrary flavour text',()=>{const s={items:{tonic:1},gold:4,cores:['earth'],supports:['focus'],party:[0],heroes:[{strain:5}]};const before={items:{tonic:3},gold:0,cores:[],supports:[],strain:13};const lines=inspectionChanges(before,s).map(e=>e.text);assert.ok(lines.includes('-2 Tonic'));assert.ok(lines.includes('+4 credits'));assert.ok(lines.includes('earth Mako recovered'));assert.ok(lines.includes('Strain eased'));});

test('a distant fixture cannot be opened, looted or recorded through the field adapter',()=>{const{w,events}=setup();const o=locate(w,o=>o.type==='furnishing'&&o.supply);w.state.x=o.xy[0]+5.5;const items=JSON.stringify(w.state.items),household=JSON.stringify(w.state.household),notes=JSON.stringify(w.state.fieldNotes);w.interact(o);assert.equal(JSON.stringify(w.state.items),items);assert.equal(JSON.stringify(w.state.household),household);assert.equal(JSON.stringify(w.state.fieldNotes),notes);assert.equal(events.length,0);assert.equal(w.state.mode,'field');});
